        nonlocal visited, path
        if current == goal:
            path.append(goal)
            return True
        if current in visited:
            return False
        visited.add(current)
        for neighbor in graph.get(current, []):
            if dfs(neighbor, path):
                path.append(current)
                return True
        return False
    path = []
    if dfs(start, path):
        return path
    return None
