def find_path(graph, start, goal):
    path = []
    seen = {start}

    def recursive_search(current):
        if current == goal:
            return [current]
        for neighbor in graph[current]:
            if neighbor not in seen:
                seen.add(neighbor)
                path_to_goal = recursive_search(neighbor)
                if path_to_goal:
                    return [current] + path_to_goal
        return None
    path = recursive_search(start)
    return path if path else None

