def find_path(graph, start, goal):
    open_set = [start]
    came_from = {}
    cost_so_far = {node: float('infinity') for node in graph}
    cost_so_far[start] = 0
    while open_set:
        current = min(open_set, key=lambda node: cost_so_far[node])
        if current == goal:
            path = [goal]
            while current in came_from:
                current = came_from[current]
                path.append(current)
            path.reverse()
            return path
        open_set.remove(current)
        closed_set = set()
        for neighbor in graph[current]:
            if neighbor in closed_set:
                continue
            tentative_cost = cost_so_far[current] + 1
            if tentative_cost < cost_so_far[neighbor]:
                came_from[neighbor] = current
                cost_so_far[neighbor] = tentative_cost
                if neighbor not in open_set:
                    open_set.append(neighbor)
    return None

